const hashPassword = (password, salt = crypto.randomBytes(16).toString('hex')) => ({ salt, hash: crypto.scryptSync(password, salt, 64).toString('hex') });
const validPassword = (password, salt, hash) => crypto.timingSafeEqual(Buffer.from(hashPassword(password, salt).hash, 'hex'), Buffer.from(hash, 'hex'));
const newToken = () => crypto.randomBytes(32).toString('hex');
const publicUser = (user) => ({ id: user.id, name: user.name, email: user.email, role: user.role });
const databaseMessage = (error) => ['ECONNREFUSED', 'ENOTFOUND', '3D000', '28P01'].includes(error.code) || /password|SASL/i.test(error.message || '')
  ? (error.code === '28P01' || /password|SASL/i.test(error.message || '') ? 'PostgreSQL credentials are incorrect. Update DATABASE_URL in .env, then load supabase/schema.sql.' : 'PostgreSQL is not available. Start PostgreSQL, create the skillconnect_hub database, and load supabase/schema.sql.')
  : 'Could not complete the request.';
const databaseError = (res, error) => { console.error('Database/API error:', error); return res.status(500).json({ message: databaseMessage(error) }); };
const adminRequired = (req, res, next) => req.user.role === 'admin' ? next() : res.status(403).json({ message: 'Admin access required.' });
const encryptionKey = () => crypto.createHash('sha256').update(process.env.VERIFICATION_ENCRYPTION_KEY || process.env.PAYSTACK_SECRET_KEY || 'skillconnect-local-verification-key').digest();
function encryptValue(value) { const iv = crypto.randomBytes(12); const cipher = crypto.createCipheriv('aes-256-gcm', encryptionKey(), iv); const encrypted = Buffer.concat([cipher.update(value, 'utf8'), cipher.final()]); return `${iv.toString('hex')}:${cipher.getAuthTag().toString('hex')}:${encrypted.toString('hex')}`; }

