app.post('/api/me/delete-account', auth, async (req, res) => { try { const result = await pool.query("UPDATE users SET deletion_requested_at = COALESCE(deletion_requested_at, NOW()) WHERE id = $1 RETURNING deletion_requested_at AS \"deletionRequestedAt\", deletion_requested_at + INTERVAL '7 days' AS \"scheduledDeletionAt\"", [req.user.id]); await pool.query('DELETE FROM sessions WHERE user_id = $1', [req.user.id]); res.json({ ...result.rows[0], message: 'Account deletion is scheduled in 7 days.' }); } catch (error) { databaseError(res, error); } });
app.post('/api/artisan/verification', auth, artisanRequired, async (req, res) => { try { const { idType, idNumber, idPhotoAssetId, selfieAssetId } = req.body; if (!idType || !idNumber || !idPhotoAssetId || !selfieAssetId) return res.status(400).json({ message: 'ID type, ID number, ID photo, and selfie are required.' }); const result = await pool.query(`UPDATE artisans SET verification_status = 'pending', verification_id_type = $1, verification_id_last4 = $2, verification_id_ciphertext = $3, verification_id_photo_url = $4, verification_selfie_url = $5, verification_rejection_reason = NULL, verified_at = NULL WHERE user_id = $6 RETURNING verification_status AS "verificationStatus", verification_id_type AS "idType", verification_id_last4 AS "idLast4"`, [idType, idNumber.slice(-4), encryptValue(idNumber), idPhotoAssetId, selfieAssetId, req.user.id]); if (!result.rows[0]) return res.status(400).json({ message: 'Create your artisan profile first.' }); res.json({ verification: result.rows[0] }); } catch (error) { databaseError(res, error); } });
app.post('/api/artisan/profile', auth, artisanRequired, async (req, res) => { try { const { name, skill, area, bio, startingPrice, imageUrl } = req.body; if (!name || !skill || !area) return res.status(400).json({ message: 'Name, skill, and area are required.' }); await pool.query('UPDATE users SET name = $1 WHERE id = $2', [name.trim(), req.user.id]); const result = await pool.query(`INSERT INTO artisans (user_id, skill, area, bio, starting_price, image_url) VALUES ($1, $2, $3, $4, $5, $6) ON CONFLICT (user_id) DO UPDATE SET skill = EXCLUDED.skill, area = EXCLUDED.area, bio = EXCLUDED.bio, starting_price = EXCLUDED.starting_price, image_url = EXCLUDED.image_url RETURNING *`, [req.user.id, skill, area, bio || null, Number(startingPrice) || null, imageUrl || null]); res.status(201).json({ artisan: result.rows[0] }); } catch (error) { databaseError(res, error); } });
app.post('/api/artisan/payout-details', auth, artisanRequired, async (req, res) => { try { const { bankName, bankCode, accountNumber } = req.body; if (!bankName || !bankCode || !/^\d{10}$/.test(accountNumber || '')) return res.status(400).json({ message: 'Bank name, bank code, and a 10-digit account number are required.' }); const artisan = (await pool.query('SELECT id FROM artisans WHERE user_id = $1', [req.user.id])).rows[0]; if (!artisan) return res.status(400).json({ message: 'Create your artisan profile first.' }); const recipient = await paystack('/transferrecipient', { method: 'POST', body: JSON.stringify({ type: 'nuban', name: req.user.name, account_number: accountNumber, bank_code: bankCode, currency: 'NGN' }) }); const result = await pool.query('UPDATE artisans SET bank_name = $1, bank_code = $2, account_number = $3, recipient_code = $4 WHERE id = $5 RETURNING bank_name AS "bankName", bank_code AS "bankCode", account_number AS "accountNumber"', [bankName, bankCode, accountNumber, recipient.recipient_code, artisan.id]); res.json({ payout: result.rows[0] }); } catch (error) { res.status(error.status || 500).json({ message: error.status ? error.message : databaseMessage(error) }); } });
app.get('/api/artisans', async (req, res) => { try { const sort = req.query.sort === 'top' ? '"averageRating" DESC NULLS LAST, "reviewCount" DESC,' : ''; const result = await pool.query(`SELECT a.id, a.user_id AS "userId", u.name, a.skill, a.area, a.bio, a.starting_price AS "startingPrice", a.image_url AS "imageUrl", (a.verification_status = 'approved') AS verified, ROUND(AVG(r.rating)::numeric, 1) AS "averageRating", COUNT(r.id)::int AS "reviewCount", CASE WHEN COUNT(r.id) >= 5 AND AVG(r.rating) >= 4.5 THEN true ELSE false END AS "topRated", CASE WHEN (SELECT COUNT(*) FROM orders o WHERE o.artisan_id = a.id AND o.status = 'confirmed') >= 10 AND NOT EXISTS (SELECT 1 FROM orders d WHERE d.artisan_id = a.id AND d.status = 'disputed') THEN true ELSE false END AS reliable FROM artisans a JOIN users u ON u.id = a.user_id LEFT JOIN reviews r ON r.artisan_id = a.id WHERE u.suspended = FALSE AND a.skill ILIKE $1 AND a.area ILIKE $2 GROUP BY a.id, u.name ORDER BY ${sort} a.created_at DESC`, [`%${req.query.service || ''}%`, `%${req.query.area || ''}%`]); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.get('/api/artisans/:id', async (req, res) => { try { const artisan = (await pool.query(`SELECT a.id, a.user_id AS "userId", u.name, a.skill, a.area, a.bio, a.starting_price AS "startingPrice", a.image_url AS "imageUrl", (a.verification_status = 'approved') AS verified, a.verification_status AS "verificationStatus", a.verification_rejection_reason AS "verificationRejectionReason", ROUND(AVG(r.rating)::numeric, 1) AS "averageRating", COUNT(r.id)::int AS "reviewCount", CASE WHEN COUNT(r.id) >= 5 AND AVG(r.rating) >= 4.5 THEN true ELSE false END AS "topRated", CASE WHEN (SELECT COUNT(*) FROM orders o WHERE o.artisan_id = a.id AND o.status = 'confirmed') >= 10 AND NOT EXISTS (SELECT 1 FROM orders d WHERE d.artisan_id = a.id AND d.status = 'disputed') THEN true ELSE false END AS reliable FROM artisans a JOIN users u ON u.id = a.user_id LEFT JOIN reviews r ON r.artisan_id = a.id WHERE a.id = $1 AND u.suspended = FALSE GROUP BY a.id, u.name`, [req.params.id])).rows[0]; if (!artisan) return res.status(404).json({ message: 'Artisan not found.' }); const products = (await pool.query('SELECT p.id, p.name, p.description, p.price, p.image_url AS "imageUrl", p.in_stock AS "inStock", ROUND(AVG(r.rating)::numeric, 1) AS "averageRating", COUNT(r.id)::int AS "reviewCount" FROM products p LEFT JOIN reviews r ON r.product_id = p.id WHERE p.artisan_id = $1 AND p.hidden = FALSE GROUP BY p.id ORDER BY p.created_at DESC', [artisan.id])).rows; const reviews = (await pool.query(`SELECT r.id, r.rating, r.comment, r.photo_url AS "photoUrl", r.customer_first_name AS "customerFirstName", r.artisan_reply AS "artisanReply", r.artisan_replied_at AS "artisanRepliedAt", r.created_at AS "createdAt", r.product_id AS "productId", EXISTS (SELECT 1 FROM review_reports rr WHERE rr.review_id = r.id) AS flagged FROM reviews r WHERE r.artisan_id = $1 AND r.hidden = FALSE ORDER BY r.created_at DESC`, [artisan.id])).rows; res.json({ artisan, products, reviews }); } catch (error) { databaseError(res, error); } });
app.post('/api/products', auth, artisanRequired, async (req, res) => { try { const { name, description, price, imageUrl, inStock = true } = req.body; const artisan = (await pool.query('SELECT id FROM artisans WHERE user_id = $1', [req.user.id])).rows[0]; if (!artisan) return res.status(400).json({ message: 'Create your artisan profile first.' }); if (!name || !price || !imageUrl) return res.status(400).json({ message: 'Product name, price, and photo URL are required.' }); const result = await pool.query('INSERT INTO products (artisan_id, name, description, price, image_url, in_stock) VALUES ($1, $2, $3, $4, $5, $6) RETURNING id, name, description, price, image_url AS "imageUrl", in_stock AS "inStock"', [artisan.id, name, description || null, Number(price), imageUrl, inStock]); res.status(201).json({ product: result.rows[0] }); } catch (error) { databaseError(res, error); } });
app.put('/api/products/:id', auth, artisanRequired, async (req, res) => { try { const { name, description, price, imageUrl, inStock } = req.body; const result = await pool.query(`UPDATE products p SET name = $1, description = $2, price = $3, image_url = $4, in_stock = $5 FROM artisans a WHERE p.id = $6 AND p.artisan_id = a.id AND a.user_id = $7 RETURNING p.id, p.name, p.description, p.price, p.image_url AS "imageUrl", p.in_stock AS "inStock"`, [name, description || null, Number(price), imageUrl, inStock, req.params.id, req.user.id]); if (!result.rows[0]) return res.status(404).json({ message: 'Product not found.' }); res.json({ product: result.rows[0] }); } catch (error) { databaseError(res, error); } });
