app.get('/api/products/:id', async (req, res) => { try { const product = (await pool.query(`SELECT p.id, p.name, p.description, p.price, p.image_url AS "imageUrl", p.in_stock AS "inStock", a.id AS "artisanId", a.user_id AS "artisanUserId", u.name AS "artisanName", a.skill, a.area FROM products p JOIN artisans a ON a.id = p.artisan_id JOIN users u ON u.id = a.user_id WHERE p.id = $1 AND p.hidden = FALSE AND u.suspended = FALSE`, [req.params.id])).rows[0]; if (!product) return res.status(404).json({ message: 'Product not found.' }); product.reviews = (await pool.query(`SELECT r.id, r.rating, r.comment, r.photo_url AS "photoUrl", r.customer_first_name AS "customerFirstName", r.artisan_reply AS "artisanReply", r.created_at AS "createdAt" FROM reviews r WHERE r.product_id = $1 AND r.hidden = FALSE ORDER BY r.created_at DESC`, [product.id])).rows; res.json(product); } catch (error) { databaseError(res, error); } });
app.get('/api/products', async (req, res) => { try { const result = await pool.query(`SELECT p.id, p.name, p.description, p.price, p.image_url AS "imageUrl", p.in_stock AS "inStock", a.id AS "artisanId", u.name AS "artisanName", a.skill, a.area FROM products p JOIN artisans a ON a.id = p.artisan_id JOIN users u ON u.id = a.user_id WHERE p.hidden = FALSE AND u.suspended = FALSE AND p.name ILIKE $1 AND a.area ILIKE $2 ORDER BY p.created_at DESC`, [`%${req.query.search || ''}%`, `%${req.query.area || ''}%`]); res.json(result.rows); } catch (error) { databaseError(res, error); } });

app.get('/api/conversations', auth, async (req, res) => { try { const result = await pool.query(`SELECT c.id, c.artisan_id AS "artisanId", u.name AS "artisanName", c.customer_id AS "customerId", cu.name AS "customerName", c.updated_at AS "updatedAt", (SELECT body FROM messages m WHERE m.conversation_id = c.id ORDER BY m.created_at DESC LIMIT 1) AS "lastMessage", (SELECT COUNT(*) FROM messages m WHERE m.conversation_id = c.id AND m.sender_id <> $1 AND m.is_read = FALSE) AS "unreadCount" FROM conversations c JOIN artisans a ON a.id = c.artisan_id JOIN users u ON u.id = a.user_id JOIN users cu ON cu.id = c.customer_id WHERE c.customer_id = $1 OR a.user_id = $1 ORDER BY c.updated_at DESC`, [req.user.id]); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.post('/api/conversations', auth, async (req, res) => { try { const artisan = (await pool.query('SELECT id FROM artisans WHERE id = $1', [req.body.artisanId])).rows[0]; if (!artisan || req.user.role === 'artisan') return res.status(400).json({ message: 'Choose a valid artisan.' }); const result = await pool.query('INSERT INTO conversations (customer_id, artisan_id) VALUES ($1, $2) ON CONFLICT (customer_id, artisan_id) DO UPDATE SET updated_at = NOW() RETURNING id', [req.user.id, artisan.id]); res.status(201).json({ id: result.rows[0].id }); } catch (error) { databaseError(res, error); } });
app.get('/api/conversations/:id/messages', auth, async (req, res) => { try { if (!await conversationAccess(req)) return res.status(403).json({ message: 'Conversation not available.' }); await pool.query('UPDATE messages SET is_read = TRUE WHERE conversation_id = $1 AND sender_id <> $2', [req.params.id, req.user.id]); const result = await pool.query(`SELECT m.id, m.body, m.image_url AS "imageUrl", m.type, m.order_id AS "orderId", m.sender_id AS "senderId", u.name AS "senderName", m.created_at AS "createdAt", o.amount, o.platform_fee AS "platformFee", o.artisan_amount AS "artisanAmount", o.description AS "orderDescription", o.status AS "orderStatus", o.product_id AS "productId", o.payment_url AS "paymentUrl", o.payout_status AS "payoutStatus" FROM messages m JOIN users u ON u.id = m.sender_id LEFT JOIN orders o ON o.id = m.order_id WHERE m.conversation_id = $1 ORDER BY m.created_at ASC`, [req.params.id]); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.post('/api/conversations/:id/messages', auth, async (req, res) => { try { if (!await conversationAccess(req)) return res.status(403).json({ message: 'Conversation not available.' }); if (containsOffPlatformDetails(req.body.body)) return res.status(400).json({ message: 'For your protection, phone numbers, bank details, and off-platform payment details are not allowed in chat. Pay only inside SkillConnect-HUB to be protected.' }); if (!req.body.body && !req.body.imageUrl) return res.status(400).json({ message: 'Write a message or attach a photo.' }); const result = await pool.query('INSERT INTO messages (conversation_id, sender_id, body, image_url) VALUES ($1, $2, $3, $4) RETURNING id, body, image_url AS "imageUrl", sender_id AS "senderId", created_at AS "createdAt"', [req.params.id, req.user.id, req.body.body || null, req.body.imageUrl || null]); await pool.query('UPDATE conversations SET updated_at = NOW() WHERE id = $1', [req.params.id]); res.status(201).json({ message: result.rows[0] }); } catch (error) { databaseError(res, error); } });

app.post('/api/conversations/:id/orders', auth, artisanRequired, async (req, res) => { try { const conversation = await conversationAccess(req); if (!conversation || conversation.artisan_user_id !== req.user.id) return res.status(403).json({ message: 'Only the artisan in this conversation can request payment.' }); const amount = Math.round(Number(req.body.amount) * 100); if (!Number.isInteger(amount) || amount <= 0 || !req.body.description) return res.status(400).json({ message: 'Amount and description are required.' }); let productId = null; if (req.body.productId) { const product = (await pool.query('SELECT id FROM products WHERE id = $1 AND artisan_id = $2', [req.body.productId, conversation.artisan_id])).rows[0]; if (!product) return res.status(400).json({ message: 'Product does not belong to this artisan.' }); productId = product.id; } const fee = Math.round(amount * feePercent / 100); const order = (await pool.query('INSERT INTO orders (conversation_id, customer_id, artisan_id, product_id, description, amount, platform_fee, artisan_amount) VALUES ($1, $2, $3, $4, $5, $6, $7, $8) RETURNING id, amount, platform_fee AS "platformFee", artisan_amount AS "artisanAmount", description, status, product_id AS "productId"', [conversation.id, conversation.customer_id, conversation.artisan_id, productId, req.body.description, amount, fee, amount - fee])).rows[0]; await pool.query("INSERT INTO messages (conversation_id, sender_id, body, type, order_id) VALUES ($1, $2, $3, 'payment_request', $4)", [req.params.id, req.user.id, req.body.description, order.id]); res.status(201).json({ order }); } catch (error) { databaseError(res, error); } });

app.delete('/api/orders/:id', auth, artisanRequired, async (req, res) => { try { const order = await orderAccess(req.params.id, req.user.id); if (!order || order.artisan_user_id !== req.user.id) return res.status(404).json({ message: 'Payment request not found.' }); if (order.status !== 'requested') return res.status(400).json({ message: 'Only unpaid requests can be cancelled.' }); await pool.query('DELETE FROM messages WHERE order_id = $1', [req.params.id]); await pool.query('DELETE FROM orders WHERE id = $1', [req.params.id]); res.status(204).end(); } catch (error) { databaseError(res, error); } });
app.post('/api/orders/:id/pay', auth, async (req, res) => { try { const order = await orderAccess(req.params.id, req.user.id); if (!order || order.customer_id !== req.user.id) return res.status(404).json({ message: 'Payment request not found.' }); if (order.status !== 'requested') return res.status(400).json({ message: 'This payment request is no longer open.' }); const data = await paystack('/transaction/initialize', { method: 'POST', body: JSON.stringify({ email: req.user.email, amount: String(order.amount), reference: `SCH_${order.id}_${crypto.randomBytes(6).toString('hex')}`, callback_url: process.env.PAYSTACK_CALLBACK_URL || undefined, metadata: { order_id: order.id, conversation_id: order.conversation_id } }) }); await pool.query('UPDATE orders SET payment_reference = $1, payment_url = $2, updated_at = NOW() WHERE id = $3', [data.reference, data.authorization_url, order.id]); res.json({ authorizationUrl: data.authorization_url, reference: data.reference }); } catch (error) { res.status(error.status || 500).json({ message: error.status ? error.message : databaseMessage(error) }); } });
app.get('/api/orders/:id/verify', auth, async (req, res) => { try { const order = await orderAccess(req.params.id, req.user.id); if (!order || order.customer_id !== req.user.id) return res.status(404).json({ message: 'Order not found.' }); if (!order.payment_reference) return res.status(400).json({ message: 'Payment has not been started.' }); const data = await paystack(`/transaction/verify/${encodeURIComponent(order.payment_reference)}`); const updated = await markPaid(order.payment_reference, data); res.json({ order: updated }); } catch (error) { res.status(error.status || 500).json({ message: error.status ? error.message : databaseMessage(error) }); } });
app.post('/api/orders/:id/deliver', auth, artisanRequired, async (req, res) => { try { const order = await orderAccess(req.params.id, req.user.id); if (!order || order.artisan_user_id !== req.user.id) return res.status(404).json({ message: 'Order not found.' }); if (order.status !== 'paid') return res.status(400).json({ message: 'Only paid orders can be marked delivered.' }); const result = await pool.query("UPDATE orders SET status = 'delivered', delivered_at = NOW(), updated_at = NOW() WHERE id = $1 RETURNING id, status, delivered_at AS \"deliveredAt\"", [order.id]); res.json({ order: result.rows[0] }); } catch (error) { databaseError(res, error); } });
app.post('/api/orders/:id/confirm', auth, async (req, res) => { try { const order = await orderAccess(req.params.id, req.user.id); if (!order || order.customer_id !== req.user.id) return res.status(404).json({ message: 'Order not found.' }); if (order.status !== 'delivered') return res.status(400).json({ message: 'Only delivered orders can be confirmed.' }); const result = await pool.query("UPDATE orders SET status = 'confirmed', confirmed_at = NOW(), updated_at = NOW() WHERE id = $1 RETURNING *", [order.id]); await createPayout(result.rows[0]); res.json({ order: (await orderAccess(order.id, req.user.id)) }); } catch (error) { databaseError(res, error); } });
app.post('/api/orders/:id/dispute', auth, async (req, res) => { try { const order = await orderAccess(req.params.id, req.user.id); if (!order || order.customer_id !== req.user.id) return res.status(404).json({ message: 'Order not found.' }); if (!['paid', 'delivered'].includes(order.status)) return res.status(400).json({ message: 'This order cannot be disputed now.' }); const result = await pool.query("UPDATE orders SET status = 'disputed', updated_at = NOW() WHERE id = $1 RETURNING id, status", [order.id]); res.json({ order: result.rows[0] }); } catch (error) { databaseError(res, error); } });
app.get('/api/orders', auth, async (req, res) => { try { await autoConfirmDelivered(); const result = await pool.query(`SELECT o.id, o.description, o.amount, o.platform_fee AS "platformFee", o.artisan_amount AS "artisanAmount", o.status, o.payout_status AS "payoutStatus", o.created_at AS "createdAt", o.updated_at AS "updatedAt", u.name AS "customerName", au.name AS "artisanName", r.id AS "reviewId", r.rating AS "reviewRating", r.comment AS "reviewComment", r.created_at AS "reviewCreatedAt" FROM orders o JOIN users u ON u.id = o.customer_id JOIN artisans a ON a.id = o.artisan_id JOIN users au ON au.id = a.user_id LEFT JOIN reviews r ON r.order_id = o.id WHERE o.customer_id = $1 OR a.user_id = $1 ORDER BY o.created_at DESC`, [req.user.id]); const totals = result.rows.reduce((sum, order) => ({ earned: sum.earned + (order.status === 'confirmed' ? Number(order.artisanAmount) : 0), pending: sum.pending + (['paid', 'delivered', 'disputed'].includes(order.status) ? Number(order.artisanAmount) : 0) }), { earned: 0, pending: 0 }); res.json({ orders: result.rows, totals }); } catch (error) { databaseError(res, error); } });

app.post('/api/orders/:id/review', auth, async (req, res) => { try { const order = await orderAccess(req.params.id, req.user.id); if (!order || order.customer_id !== req.user.id || order.status !== 'confirmed') return res.status(403).json({ message: 'Only a customer with a confirmed order can review it.' }); const rating = Number(req.body.rating); if (!Number.isInteger(rating) || rating < 1 || rating > 5) return res.status(400).json({ message: 'Rating must be a whole number from 1 to 5.' }); if ((req.body.comment || '').length > 500) return res.status(400).json({ message: 'Comment must be 500 characters or less.' }); const existing = (await pool.query('SELECT id FROM reviews WHERE order_id = $1', [order.id])).rows[0]; if (existing) return res.status(409).json({ message: 'This order already has a review.' }); const customer = (await pool.query('SELECT name FROM users WHERE id = $1', [req.user.id])).rows[0]; const review = (await pool.query('INSERT INTO reviews (order_id, customer_id, artisan_id, product_id, rating, comment, photo_url, customer_first_name) VALUES ($1, $2, $3, $4, $5, $6, $7, $8) RETURNING id, rating, comment, photo_url AS "photoUrl", customer_first_name AS "customerFirstName", created_at AS "createdAt"', [order.id, req.user.id, order.artisan_id, order.product_id, rating, req.body.comment || null, req.body.photoUrl || null, customer.name.trim().split(/\s+/)[0]])).rows[0]; res.status(201).json({ review }); } catch (error) { databaseError(res, error); } });
app.put('/api/reviews/:id', auth, async (req, res) => { try { const review = (await pool.query('SELECT * FROM reviews WHERE id = $1 AND customer_id = $2', [req.params.id, req.user.id])).rows[0]; if (!review) return res.status(404).json({ message: 'Review not found.' }); if (Date.now() - new Date(review.created_at).getTime() > 7 * 24 * 60 * 60 * 1000) return res.status(400).json({ message: 'Reviews can only be edited within 7 days.' }); const rating = Number(req.body.rating); if (!Number.isInteger(rating) || rating < 1 || rating > 5) return res.status(400).json({ message: 'Rating must be a whole number from 1 to 5.' }); if ((req.body.comment || '').length > 500) return res.status(400).json({ message: 'Comment must be 500 characters or less.' }); const updated = (await pool.query('UPDATE reviews SET rating = $1, comment = $2, photo_url = $3, updated_at = NOW() WHERE id = $4 RETURNING id, rating, comment, photo_url AS "photoUrl", customer_first_name AS "customerFirstName", created_at AS "createdAt"', [rating, req.body.comment || null, req.body.photoUrl || null, review.id])).rows[0]; res.json({ review: updated }); } catch (error) { databaseError(res, error); } });
app.post('/api/reviews/:id/reply', auth, artisanRequired, async (req, res) => { try { const review = (await pool.query('SELECT r.*, a.user_id FROM reviews r JOIN artisans a ON a.id = r.artisan_id WHERE r.id = $1', [req.params.id])).rows[0]; if (!review || review.user_id !== req.user.id) return res.status(404).json({ message: 'Review not found.' }); if (review.artisan_reply) return res.status(409).json({ message: 'This review already has a reply.' }); if (!req.body.reply || req.body.reply.length > 500) return res.status(400).json({ message: 'Reply is required and must be 500 characters or less.' }); const updated = (await pool.query('UPDATE reviews SET artisan_reply = $1, artisan_replied_at = NOW(), updated_at = NOW() WHERE id = $2 RETURNING artisan_reply AS "artisanReply", artisan_replied_at AS "artisanRepliedAt"', [req.body.reply, review.id])).rows[0]; res.status(201).json({ reply: updated }); } catch (error) { databaseError(res, error); } });
app.post('/api/reviews/:id/report', async (req, res) => { try { if (!['fake', 'rude', 'wrong_person'].includes(req.body.reason)) return res.status(400).json({ message: 'Choose fake, rude, or wrong person.' }); let reporter = null; const authHeader = req.headers.authorization || ''; if (authHeader.startsWith('Bearer ')) reporter = (await pool.query('SELECT user_id FROM sessions WHERE token = $1 AND expires_at > NOW()', [authHeader.slice(7)])).rows[0]?.user_id || null; await pool.query('INSERT INTO review_reports (review_id, reported_by, reason) VALUES ($1, $2, $3) ON CONFLICT DO NOTHING', [req.params.id, reporter, req.body.reason]); res.status(201).json({ message: 'Review reported.' }); } catch (error) { databaseError(res, error); } });

app.post('/api/messages/:id/report', auth, async (req, res) => { try { const message = (await pool.query('SELECT m.id, m.conversation_id FROM messages m JOIN conversations c ON c.id = m.conversation_id JOIN artisans a ON a.id = c.artisan_id WHERE m.id = $1 AND (c.customer_id = $2 OR a.user_id = $2)', [req.params.id, req.user.id])).rows[0]; if (!message) return res.status(404).json({ message: 'Message not found.' }); await pool.query('INSERT INTO reported_messages (message_id, reported_by, reason) VALUES ($1, $2, $3) ON CONFLICT DO NOTHING', [message.id, req.user.id, req.body.reason || 'Reported by user']); res.status(201).json({ message: 'Message reported.' }); } catch (error) { databaseError(res, error); } });

async function audit(adminId, action, targetType, targetId, details = {}) { await pool.query('INSERT INTO audit_logs (admin_id, action, target_type, target_id, details) VALUES ($1, $2, $3, $4, $5)', [adminId, action, targetType, targetId || null, JSON.stringify(details)]); }
app.get('/api/admin/dashboard', auth, adminRequired, async (req, res) => { try { const counts = (await pool.query(`SELECT (SELECT COUNT(*) FROM users WHERE role <> 'admin') AS users, (SELECT COUNT(*) FROM artisans) AS artisans, (SELECT COUNT(*) FROM artisans WHERE verification_status = 'pending') AS pending_verifications, (SELECT COUNT(*) FROM orders WHERE status = 'disputed') AS open_disputes, (SELECT COUNT(*) FROM orders WHERE payout_status = 'failed') AS failed_payouts, ((SELECT COUNT(*) FROM review_reports) + (SELECT COUNT(*) FROM reported_messages)) AS reported_items, (SELECT COALESCE(SUM(amount), 0) FROM orders WHERE status IN ('paid', 'delivered', 'confirmed', 'disputed')) AS total_paid, (SELECT COALESCE(SUM(platform_fee), 0) FROM orders WHERE status IN ('paid', 'delivered', 'confirmed', 'disputed')) AS total_fees`)).rows[0]; const newestOrders = (await pool.query(`SELECT o.id, o.description, o.amount, o.status, o.created_at AS "createdAt", u.name AS "customerName", au.name AS "artisanName" FROM orders o JOIN users u ON u.id = o.customer_id JOIN artisans a ON a.id = o.artisan_id JOIN users au ON au.id = a.user_id ORDER BY o.created_at DESC LIMIT 10`)).rows; res.json({ counts, newestOrders }); } catch (error) { databaseError(res, error); } });
app.get('/api/admin/artisans', auth, adminRequired, async (req, res) => { try { const result = await pool.query(`SELECT a.id, u.name, u.email, a.skill, a.area, a.verification_status AS "verificationStatus", a.verification_id_type AS "idType", a.verification_id_last4 AS "idLast4", (a.verification_id_photo_url IS NOT NULL) AS "hasIdPhoto", (a.verification_selfie_url IS NOT NULL) AS "hasSelfie", a.verification_rejection_reason AS "rejectionReason" FROM artisans a JOIN users u ON u.id = a.user_id WHERE ($1 = '' OR a.verification_status = $1) ORDER BY a.created_at DESC`, [req.query.status || 'pending']); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.get('/api/admin/artisans/:id/private-images', auth, adminRequired, async (req, res) => { try { const artisan = (await pool.query('SELECT verification_id_photo_url AS "idPhoto", verification_selfie_url AS selfie FROM artisans WHERE id = $1', [req.params.id])).rows[0]; if (!artisan) return res.status(404).json({ message: 'Artisan not found.' }); res.json({ idPhotoUrl: signedPrivateImage(artisan.idPhoto), selfieUrl: signedPrivateImage(artisan.selfie) }); } catch (error) { res.status(500).json({ message: 'Private verification photos are unavailable.' }); } });
app.post('/api/admin/artisans/:id/decision', auth, adminRequired, async (req, res) => { try { if (!['approved', 'rejected'].includes(req.body.decision)) return res.status(400).json({ message: 'Decision must be approved or rejected.' }); const result = await pool.query(`UPDATE artisans SET verification_status = $1::varchar, verification_rejection_reason = $2, verified_at = CASE WHEN $1::text = 'approved' THEN NOW() ELSE NULL END WHERE id = $3 RETURNING id, verification_status AS "verificationStatus", verification_rejection_reason AS "rejectionReason"`, [req.body.decision, req.body.decision === 'rejected' ? (req.body.reason || 'Please upload clearer verification details.') : null, req.params.id]); if (!result.rows[0]) return res.status(404).json({ message: 'Artisan not found.' }); await audit(req.user.id, `artisan_${req.body.decision}`, 'artisan', req.params.id, { reason: req.body.reason || null }); res.json({ artisan: result.rows[0] }); } catch (error) { databaseError(res, error); } });
app.get('/api/admin/disputes', auth, adminRequired, async (req, res) => { try { const result = await pool.query(`SELECT o.id, o.description, o.amount, o.platform_fee AS "platformFee", o.artisan_amount AS "artisanAmount", o.status, o.payment_reference AS "paymentReference", o.created_at AS "createdAt", u.name AS "customerName", u.email AS "customerEmail", au.name AS "artisanName", c.id AS "conversationId" FROM orders o JOIN users u ON u.id = o.customer_id JOIN artisans a ON a.id = o.artisan_id JOIN users au ON au.id = a.user_id JOIN conversations c ON c.id = o.conversation_id WHERE o.status = 'disputed' ORDER BY o.updated_at DESC`); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.get('/api/admin/orders/:id/messages', auth, adminRequired, async (req, res) => { try { const order = (await pool.query('SELECT o.id, o.status, o.conversation_id AS "conversationId" FROM orders o WHERE o.id = $1', [req.params.id])).rows[0]; if (!order) return res.status(404).json({ message: 'Order not found.' }); const allowed = order.status === 'disputed' || (await pool.query('SELECT 1 FROM reported_messages rm JOIN messages m ON m.id = rm.message_id WHERE m.conversation_id = $1 LIMIT 1', [order.conversationId])).rows[0]; if (!allowed) return res.status(403).json({ message: 'Admin chat access is limited to disputed or reported conversations.' }); const messages = (await pool.query('SELECT m.id, m.body, m.image_url AS "imageUrl", m.created_at AS "createdAt", u.name AS "senderName" FROM messages m JOIN users u ON u.id = m.sender_id WHERE m.conversation_id = $1 ORDER BY m.created_at ASC', [order.conversationId])).rows; res.json({ order, messages }); } catch (error) { databaseError(res, error); } });
app.post('/api/admin/orders/:id/resolve', auth, adminRequired, async (req, res) => { try { const order = (await pool.query('SELECT * FROM orders WHERE id = $1', [req.params.id])).rows[0]; if (!order || order.status !== 'disputed') return res.status(400).json({ message: 'Only disputed orders can be resolved here.' }); const action = req.body.action; if (!['refund_full', 'refund_partial', 'release', 'fix_on_hold'].includes(action)) return res.status(400).json({ message: 'Unknown resolution.' }); let refundReference = null; let refundAmount = null; if (action === 'refund_full' || action === 'refund_partial') { refundAmount = action === 'refund_full' ? order.amount : Math.round(Number(req.body.amount) * 100); if (!refundAmount || refundAmount <= 0 || refundAmount > order.amount) return res.status(400).json({ message: 'Refund amount is invalid.' }); const refund = await paystack('/refund', { method: 'POST', body: JSON.stringify({ transaction: order.payment_reference, amount: refundAmount, customer_note: req.body.note || 'SkillConnect-HUB dispute resolution', merchant_note: `Admin resolution for order ${order.id}`, reference: `SCH_REFUND_${order.id}_${Date.now()}` }) }); refundReference = refund.reference || null; } const nextStatus = action === 'release' ? 'confirmed' : action === 'fix_on_hold' ? 'disputed' : 'refunded'; const result = await pool.query('UPDATE orders SET status = $1::varchar, admin_decision = $2, admin_note = $3, refund_amount = $4, refund_reference = $5, confirmed_at = CASE WHEN $1::text = \'confirmed\' THEN NOW() ELSE confirmed_at END, updated_at = NOW() WHERE id = $6 RETURNING *', [nextStatus, action, req.body.note || null, refundAmount, refundReference, order.id]); await pool.query('INSERT INTO messages (conversation_id, sender_id, body, type) VALUES ($1, $2, $3, \'text\')', [order.conversation_id, req.user.id, `Admin decision: ${action.replace('_', ' ')}.${req.body.note ? ` ${req.body.note}` : ''}`]); if (action === 'release') await createPayout(result.rows[0]); await audit(req.user.id, `dispute_${action}`, 'order', order.id, { note: req.body.note || null, refundAmount }); res.json({ order: result.rows[0] }); } catch (error) { res.status(error.status || 500).json({ message: error.status ? error.message : databaseMessage(error) }); } });
app.get('/api/admin/reviews/reported', auth, adminRequired, async (req, res) => { try { const result = await pool.query(`SELECT r.id, r.rating, r.comment, r.customer_first_name AS "customerFirstName", r.hidden, o.id AS "orderId", u.name AS "customerName", au.name AS "artisanName", ARRAY_AGG(DISTINCT rr.reason) AS reasons FROM reviews r JOIN orders o ON o.id = r.order_id JOIN users u ON u.id = r.customer_id JOIN artisans a ON a.id = r.artisan_id JOIN users au ON au.id = a.user_id JOIN review_reports rr ON rr.review_id = r.id GROUP BY r.id, o.id, u.name, au.name ORDER BY r.created_at DESC`); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.post('/api/admin/reviews/:id/action', auth, adminRequired, async (req, res) => { try { const review = (await pool.query('SELECT * FROM reviews WHERE id = $1', [req.params.id])).rows[0]; if (!review) return res.status(404).json({ message: 'Review not found.' }); if (!['keep', 'hide', 'warn'].includes(req.body.action)) return res.status(400).json({ message: 'Unknown review action.' }); if (req.body.action === 'hide') await pool.query('UPDATE reviews SET hidden = TRUE, hidden_reason = $1 WHERE id = $2', [req.body.reason || 'Hidden by admin', review.id]); if (req.body.action === 'warn') await pool.query('UPDATE users SET warnings = warnings + 1 WHERE id = $1', [review.customer_id]); await audit(req.user.id, `review_${req.body.action}`, 'review', review.id, { reason: req.body.reason || null }); res.json({ message: 'Review action saved.' }); } catch (error) { databaseError(res, error); } });
app.get('/api/admin/messages/reported', auth, adminRequired, async (req, res) => { try { const result = await pool.query(`SELECT rm.id, rm.message_id AS "messageId", rm.reason, rm.created_at AS "createdAt", m.body, c.id AS "conversationId", u.name AS "reportedBy" FROM reported_messages rm JOIN messages m ON m.id = rm.message_id JOIN conversations c ON c.id = m.conversation_id LEFT JOIN users u ON u.id = rm.reported_by ORDER BY rm.created_at DESC`); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.get('/api/admin/users', auth, adminRequired, async (req, res) => { try { const term = `%${req.query.q || ''}%`; const result = await pool.query('SELECT id, name, email, phone, role, suspended, suspension_reason AS "suspensionReason", warnings, created_at AS "createdAt" FROM users WHERE name ILIKE $1 OR email ILIKE $1 OR COALESCE(phone, \'\') ILIKE $1 ORDER BY created_at DESC LIMIT 100', [term]); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.post('/api/admin/users/:id/suspension', auth, adminRequired, async (req, res) => { try { if (Number(req.params.id) === req.user.id) return res.status(400).json({ message: 'You cannot suspend your own admin account.' }); const suspended = Boolean(req.body.suspended); const result = await pool.query('UPDATE users SET suspended = $1, suspension_reason = $2 WHERE id = $3 RETURNING id, suspended, suspension_reason AS "suspensionReason"', [suspended, suspended ? (req.body.reason || 'Suspended by admin') : null, req.params.id]); if (!result.rows[0]) return res.status(404).json({ message: 'User not found.' }); if (suspended) await pool.query('DELETE FROM sessions WHERE user_id = $1', [req.params.id]); await audit(req.user.id, suspended ? 'user_suspend' : 'user_unsuspend', 'user', req.params.id, { reason: req.body.reason || null }); res.json({ user: result.rows[0] }); } catch (error) { databaseError(res, error); } });
app.delete('/api/admin/products/:id', auth, adminRequired, async (req, res) => { try { const result = await pool.query('UPDATE products SET hidden = TRUE WHERE id = $1 RETURNING id', [req.params.id]); if (!result.rows[0]) return res.status(404).json({ message: 'Product not found.' }); await audit(req.user.id, 'product_hide', 'product', req.params.id, { reason: req.body?.reason || null }); res.status(204).end(); } catch (error) { databaseError(res, error); } });
app.get('/api/admin/payouts/failed', auth, adminRequired, async (req, res) => { try { const result = await pool.query(`SELECT o.id, o.artisan_amount AS "artisanAmount", o.payout_error AS "payoutError", o.payout_reference AS "payoutReference", u.name AS "artisanName", u.email AS "artisanEmail" FROM orders o JOIN artisans a ON a.id = o.artisan_id JOIN users u ON u.id = a.user_id WHERE o.payout_status = 'failed' ORDER BY o.updated_at DESC`); res.json(result.rows); } catch (error) { databaseError(res, error); } });
app.post('/api/admin/orders/:id/retry-payout', auth, adminRequired, async (req, res) => { try { const order = (await pool.query('SELECT * FROM orders WHERE id = $1 AND payout_status = \'failed\'', [req.params.id])).rows[0]; if (!order) return res.status(404).json({ message: 'Failed payout not found.' }); await createPayout(order); await audit(req.user.id, 'payout_retry', 'order', order.id); res.json({ order: (await pool.query('SELECT id, payout_status AS "payoutStatus", payout_error AS "payoutError", payout_reference AS "payoutReference" FROM orders WHERE id = $1', [order.id])).rows[0] }); } catch (error) { databaseError(res, error); } });

async function markPaid(reference, transaction) { const order = (await pool.query('SELECT * FROM orders WHERE payment_reference = $1', [reference])).rows[0]; if (!order) return null; if (transaction.status && transaction.status !== 'success') return order; if (Number(transaction.amount) !== Number(order.amount)) throw new Error('Paystack amount does not match the order.'); if (order.status === 'requested') return (await pool.query("UPDATE orders SET status = 'paid', paid_at = NOW(), updated_at = NOW() WHERE id = $1 RETURNING *", [order.id])).rows[0]; return order; }
async function createPayout(order) { const payoutReference = order.payout_reference || `SCH_PAYOUT_${order.id}`; try { const artisan = (await pool.query('SELECT * FROM artisans WHERE id = $1', [order.artisan_id])).rows[0]; if (!artisan?.recipient_code) { await pool.query('UPDATE orders SET payout_status = $1, payout_reference = $2, payout_error = $3, updated_at = NOW() WHERE id = $4', ['failed', payoutReference, 'Artisan payout details are not configured.', order.id]); return; } const transfer = await paystack('/transfer', { method: 'POST', body: JSON.stringify({ source: 'balance', amount: String(order.artisan_amount), recipient: artisan.recipient_code, reason: `SkillConnect-HUB order ${order.id}`, reference: payoutReference }) }); await pool.query('UPDATE orders SET payout_status = $1, payout_reference = $2, payout_error = NULL, updated_at = NOW() WHERE id = $3', ['processing', transfer.reference || payoutReference, order.id]); } catch (error) { await pool.query('UPDATE orders SET payout_status = $1, payout_reference = $2, payout_error = $3, updated_at = NOW() WHERE id = $4', ['failed', payoutReference, error.message, order.id]); } }
async function autoConfirmDelivered() { const rows = (await pool.query("UPDATE orders SET status = 'confirmed', confirmed_at = NOW(), updated_at = NOW() WHERE status = 'delivered' AND delivered_at <= NOW() - INTERVAL '48 hours' RETURNING *")).rows; for (const order of rows) await createPayout(order); }
async function sendReviewReminders() { if (!mailer) return; const rows = (await pool.query(`SELECT o.id, u.email, u.name, auser.name AS artisan_name FROM orders o JOIN users u ON u.id = o.customer_id JOIN artisans a ON a.id = o.artisan_id JOIN users auser ON auser.id = a.user_id LEFT JOIN reviews r ON r.order_id = o.id WHERE o.status = 'confirmed' AND o.confirmed_at <= NOW() - INTERVAL '24 hours' AND o.review_reminder_sent_at IS NULL AND r.id IS NULL`)).rows; for (const order of rows) { try { await mailer.sendMail({ from: process.env.SMTP_FROM || process.env.SMTP_USER, to: order.email, subject: 'How was your SkillConnect-HUB order?', text: `Hi ${order.name.split(/\s+/)[0]}, how was your order from ${order.artisan_name}? Leave a review in SkillConnect-HUB.` }); await pool.query('UPDATE orders SET review_reminder_sent_at = NOW() WHERE id = $1', [order.id]); } catch (error) { console.error(`Review reminder failed for order ${order.id}: ${error.message}`); } } }
setInterval(() => autoConfirmDelivered().catch((error) => console.error(`Automatic confirmation failed: ${error.message}`)), 15 * 60 * 1000).unref();
setInterval(() => sendReviewReminders().catch((error) => console.error(`Review reminder scan failed: ${error.message}`)), 60 * 60 * 1000).unref();

async function ensureAdmin() { if (!process.env.ADMIN_EMAIL || !process.env.ADMIN_PASSWORD) return; const { salt, hash } = hashPassword(process.env.ADMIN_PASSWORD); await pool.query(`INSERT INTO users (name, email, password_hash, password_salt, role) VALUES ('Administrator', LOWER($1), $2, $3, 'admin') ON CONFLICT (email) DO UPDATE SET role = 'admin', password_hash = EXCLUDED.password_hash, password_salt = EXCLUDED.password_salt, suspended = FALSE`, [process.env.ADMIN_EMAIL, hash, salt]); console.log(`Admin account ready: ${process.env.ADMIN_EMAIL}`); }
pool.on('error', (error) => console.error(`PostgreSQL pool error: ${error.message}`));
app.use((error, _req, res, _next) => { console.error(error); res.status(500).json({ message: databaseMessage(error) }); });
async function start() {
  try {
    await pool.query('SELECT 1');
    await runMigrations();
    await pool.query("DELETE FROM users WHERE deletion_requested_at <= NOW() - INTERVAL '7 days'");
    await ensureAdmin();
    console.log('PostgreSQL connected and schema is ready.');
  } catch (error) {
    console.error(`Database connection failed: ${databaseMessage(error)} Detail: ${error.message}`);
  }
  app.listen(port, () => console.log(`SkillConnect-HUB API running on port ${port}`));
}
start();
setInterval(() => pool.query("DELETE FROM users WHERE deletion_requested_at <= NOW() - INTERVAL '7 days'").catch((error) => console.error(`Scheduled account deletion failed: ${error.message}`)), 60 * 60 * 1000).unref();
